tools.example:
a = sym(1/3)              % exact 1/3, not 0.3333...
b = sym(0.1, 'f')         % exact binary value of the double 0.1
M = sym('m', [2 2]);
v = sym('v', [3 1], 'positive');
disp(a + sym(1/6))        % 1/2

syms x y a
solve(a*x^2 + 5*x + 6 == 0, x)
S = solve([x + y == 3, x^2 + y^2 == 5], [x, y]);
disp([S.x, S.y])
[sol, params, conds] = solve(sin(x) == 0.5, x, 'ReturnConditions', true);
fprintf('%s with %s\n', char(sol), char(conds));

syms y(t) m k c
Dy = diff(y, t);
D2y = diff(y, t, 2);
sol = dsolve(m*D2y + c*Dy + k*y == 0, [y(0) == 1, Dy(0) == 0]);
sol = simplify(subs(sol, [m c k], [1 0.5 4]));
fplot(sol, [0 20])

syms y(t)
eqn = diff(y, t, 2) + 5*diff(y, t) + 6*y == sin(t);
[V, S] = odeToVectorField(eqn);
M = matlabFunction(V, 'Vars', {'t', 'Y'});
[tt, yy] = ode45(M, [0 10], [1; 0]);
plot(tt, yy(:,1))
disp(S)

syms s t
H = 1/(s^2 + 2*s + 5);
h = ilaplace(H, s, t)
stepResp = simplify(ilaplace(H/s, s, t));
fplot(stepResp, [0 6])

syms z n
H = z / (z^2 - 1.5*z + 0.5);
h = simplify(iztrans(H, z, n))
vals = double(subs(h, n, 0:8));
stem(0:8, vals)

syms x1 x2 u
f = [x2; -sin(x1) - 0.1*x2 + u];
A = jacobian(f, [x1; x2]);
B = jacobian(f, u);
Alin = double(subs(A, [x1 x2], [0 0]));
disp(Alin)

syms x y
f = x^3 - 3*x*y + y^3;
H = hessian(f, [x y])
crit = solve(gradient(f, [x y]) == 0, [x y]);
Hc = double(subs(H, [x y], [crit.x(2) crit.y(2)]));
eig(Hc)

syms x y z
V = x^2*y + y*z^3;
g = gradient(V, [x y z])
gfun = matlabFunction(g, 'Vars', {[x y z]});
disp(gfun([1 2 3]))

syms x y z
V = [x^2*y, y*z, z*x^2];
divergence(V, [x y z])
E = [x, y, z] / (x^2 + y^2 + z^2)^(3/2);
simplify(divergence(E, [x y z]))          % 0 away from the origin

syms x y z
V = [-y, x, 0];
curl(V, [x y z])                         % [0 0 2]
F = gradient(x^2*y*z, [x y z]);
simplify(curl(F, [x y z]))               % zero: gradients are curl-free

old = digits(60);
x = vpa(sqrt(sym(2)));
disp(x)
digits(old);   % restore

syms x y
f = x^2 + 3*x*y + exp(-y);
g = gradient(f, [x y]);
fh = matlabFunction(f, 'Vars', {[x y]});
gh = matlabFunction(g, 'Vars', {[x y]});
opts = optimoptions('fminunc', 'SpecifyObjectiveGradient', true);
obj = @(v) deal(fh(v), gh(v));
xmin = fminunc(obj, [1 1], opts);

syms x y z a
eqns = [x + 2*y - z == 4, 3*x - y + 2*z == a, -x + y + z == 0];
[A, b] = equationsToMatrix(eqns, [x y z]);
disp(A), disp(b)
sol = linsolve(A, b);
disp(simplify(sol))

syms a b c
A = [1 2 3; 4 5 6; 7 8 9];
B = [a; b; c];
X = linsolve(A, B);
disp(simplify(X))
A2 = sym([2 1; 1 3]);
disp(linsolve(A2, sym([5; 10])))
